from ta5g_throughput.assertions import ThroughputAnalyze
from ta5g_throughput.data_traffic import DataTraffic
from ta5g_throughput.throughput_measurement import ThroughputMeasurement
from robot.api import logger


class ta5g_throughput(object):
    """
    This library supports getting UE and cell based throughput in Mbps, based on egate console output of ue_stats
    and cell_stats respectively. It includes keywords that return the throughput values and keywords that do the
    throughput verification.
    """

    @staticmethod
    def get_throughput_for_ue(ue_id, selection_type, direction, layer='physical', scells='all', retry=0, precision=2):
        """
        Gets throughput for a given UE and given direction in Mbps. Throughput is returned with two digit
        floating point precision.
        :param ue_id:               UE id.
        :param selection_type:      Statistics of throughput per one cell:'current' or 'minimum' or 'maximum' or
        'average'.
        :param direction:           'dl' or 'ul'.
        :param layer:               'mac' or 'physical'.
        :param scells:              list of serving cells to count throughput in format number,number[...]. 0 is for
        PCell and 1,2,... for SCells. If more than one serving cell is provided than the method will return the sum
        of throughputs in all given cells. Second option is choice between 'pcell', 'scells' and 'all' that will return
        throughput of PCell, the sum of SCells throughputs or the aggregated throughput.
        :param retry:               number of retry after incorrect read egate output
        :param precision:           precision for return value.
        :return:                    UE throughput in Mbps.
        """
        return ThroughputMeasurement().get_ue_throughput(
            ue_id, selection_type, direction, layer, scells, retry, int(precision)
        )

    @staticmethod
    def get_throughput_for_cell(cell_id, selection_type, direction, layer='mac', retry=0):
        """
        Gets throughput for a given cell and given direction in Mbps. Throughput is returned with two digit
        floating point precision.
        :param cell_id:             cell id.
        :param selection_type:      Statistics of throughput per one cell:'current' or 'minimum' or 'maximum' or
        'average'.
        :param direction:           'dl' or 'ul'.
        :param layer:               'mac' or 'physical'.
        :param retry:               number of retry after incorrect read egate output
        :return:                    Cell throughput in Mbps.
        """
        return ThroughputMeasurement().get_cell_throughput(cell_id, selection_type, direction, layer, retry)

    @staticmethod
    def expected_throughput_for_ue_should_be_reached(
        ue_id, throughput, direction, selection_type, margin=0.5, layer='physical', scells='all', retry=3, precision=2, cell_group=None
    ):
        """
        Verifies that given throughput for given ue is achieved. Raises an exception when the throughput is lower
        than expected with given margin.
        :param ue_id:           egate UE id
        :param throughput:      expected throughput in Mbps
        :param margin:          possible margin of error
        :param direction:       'dl' or 'ul'
        :param selection_type:  'current' or 'minimum' or 'maximum' or 'average'
        :param layer:           'mac' or 'physical'
        :param retry:           number of retry after incorrect read egate output
        :param precision:       precision for measured throughput.
        :return:                None
        """
        ThroughputAnalyze.expected_throughput_for_ue_should_be_reached(
            ue_id, throughput, margin, direction, selection_type, layer, scells, retry, int(precision), cell_group
        )

    @staticmethod
    def expected_throughput_for_list_of_ues_should_be_reached(
        ues_list, throughput, direction, selection_type, margin=0.5, layer='physical', scells='all', retry=0, precision=2
    ):
        """
        Verifies that given throughput for list of given ues is achieved. Raises an exception when the throughput
        for any of ues is lower than expected with given margin.
        :param ues_list:        list of egate UEs
        :param throughput:      expected throughput in Mbps
        :param margin:          possible margin of error
        :param direction:       'dl' or 'ul'
        :param selection_type:  'current' or 'minimum' or 'maximum' or 'average'
        :param layer:           'mac' or 'physical'
        :param retry:           number of retry after incorrect read egate output
        :param precision:       precision for measured throughput.
        :return:                None
        """
        ThroughputAnalyze.expected_throughput_for_list_of_ues_should_be_reached(
            ues_list, throughput, margin, direction, selection_type, layer, scells, retry, int(precision)
        )

    @staticmethod
    def expected_throughput_for_cell_should_be_reached(
        cell_id, throughput, direction, selection_type, layer='mac', margin=0.5, enb_id=1, retry=0
    ):
        """
        Verifies that given throughput for given cell is achieved. Raises an exception when the throughput is lower
        than expected with given margin.
        :param cell_id:         egate cell id
        :param throughput:      expected throughput in Mbps
        :param margin:          possible margin of error
        :param direction:       'dl' or 'ul'
        :param selection_type:  'current' or 'minimum' or 'maximum' or 'average'
        :param layer:           'mac' or 'physical'
        :param retry:           number of retry after incorrect read egate output
        :param enb_id: id of enb
        :return:                None
        """
        logger.console("Keyword is not working as expected due to limitations of wts command cell_stats_nr, please remove it from your test")
        ThroughputAnalyze.expected_throughput_for_cell_should_be_reached(
            cell_id, throughput, margin, direction, selection_type, layer, enb_id, retry,
        )

    @staticmethod
    def expected_throughput_for_bearer_should_be_reached(ue_id, bearer_id, throughput, direction='dl',
                                                         selection_type='average', margin='10%', retry=0):
        """
        Verifies that given throughput for given bearer is achieved.
        Raises an exception when the throughput is lower than
        expected with given margin.
        :param ue: egate ue id
        :param bearer: egate bearer id
        :param throughput: expected throughput in Mbps
        :param margin: possible margin of error
        :param direction: 'dl' or 'ul'
        :param selection_type: 'minimum' or 'maximum' or 'average' (default average)
        :param retry: number of retry after incorrect read egate output
        """
        ThroughputAnalyze.expected_throughput_for_bearer_should_be_reached(ue_id, bearer_id, throughput, direction,
                                                                           selection_type, margin, retry)

    @staticmethod
    def start_data_traffic(
        ues,
        direction,
        pdu=None,
        bearer_id=None,
        throughput=None,
        last_ue_id=None,
        traffic_id=None,
        traffic_period=None,
        optional_parameters=None,
    ):
        """
        Starts sending data to/from UE.
        :param ues:                     List of UEs or single UE ID, or first UE ID (if range of UEs will be used)
        :param bearer_id:               Bearer id
        :param direction:               Direction: ul/dl/both
        :param throughput:              [optional] Throughput with units (bps, kbps or mbps)
        :param last_ue_id:              Id of last ue, when range of ues is used
        :param traffic_id:              [optional] Traffic ID
        :param traffic_period:          [optional] Period in which data will be sending/receiving, if 'None' then
        traffic will be constantly generated.
        :param optional_parameters:     [optional] Any other parameters that emulator can handle with
        :return:                        None

        Example usage with last_ue_id with range ue's id from 1 to 500, bearer_id=1,
        direction: download and throughput 37kbps:
        Start Data Traffic    ues=1    bearer_id=1    direction=dl    throughput=37kbps    last_ue_id=500
        """
        DataTraffic().start_data_traffic(
            ues=ues, direction=direction, pdu=pdu, bearer_id=bearer_id,
            throughput=throughput, last_ue_id=last_ue_id, traffic_id=traffic_id, traffic_period=traffic_period,
            optional_parameters=optional_parameters
        )

    @staticmethod
    def start_and_check_data_traffic(ues, direction, pdu=None,
                                     bearer_id=None, throughput=None, last_ue_id=None, traffic_id=None, traffic_period=None,
                                     optional_parameters=None, **kwargs):
        """
        Starts and checks data traffic for UEs
        :param ues:                     List of UEs or single UE ID, or first UE ID (if range of UEs will be used)
        :param bearer_id:               Bearer id
        :param direction:               Direction: ul/dl/both
        :param throughput:              [optional] Throughput with units (bps, kbps or mbps)
        :param last_ue_id:              Id of last ue, when range of ues is used
        :param traffic_id:              [optional] Traffic ID
        :param traffic_period:          [optional] Period in which data will be generated
        :param optional_parameters:     optional parameters for Egate
        :return: None

        Example usage with last_ue_id with range ue_id from 1 to 500, bearer_id=1,
        direction: download and throughput 37kbps:
        Start And Check Data Traffic    ues=1    bearer_id=1    direction=dl    throughput=37kbps    last_ue_id=500
        """
        DataTraffic().start_and_check_data_traffic(
            ues=ues, direction=direction, pdu=pdu, bearer_id=bearer_id,
            throughput=throughput, last_ue_id=last_ue_id, traffic_id=traffic_id, traffic_period=traffic_period,
            optional_parameters=optional_parameters, **kwargs
        )

    @staticmethod
    def stop_data_traffic(ues, pdu=None, bearer_id=None, last_ue_id=None, direction=None, traffic_id=None):
        """
        Stops sending data to/from UE.
        :param ues:         List of UEs
        :param bearer_id:   [optional] Bearer ID
        :param direction:   [optional] Direction
        :param traffic_id:  [optional] Traffic ID
        :return:            None
        """
        DataTraffic().stop_data_traffic(ues=ues, pdu=pdu, bearer_id=bearer_id, last_ue_id=last_ue_id, direction=direction, traffic_id=traffic_id)

    @staticmethod
    def generate_big_traffic(ue_id, direction, throughput_mbps, bearer_id=1):
        """
        Generates traffic that is greater than 150 Mbps
        :param ue_id:               UE ID
        :param direction:           Direction
        :param throughput_mbps:     Throughput in Mbps
        :param bearer_id:           [optional] Bearer ID
        :return:                    None
        """
        DataTraffic().generate_big_traffic(ue_id, direction, throughput_mbps, bearer_id)

    @staticmethod
    def get_bler_for_cell(cell, direction):
        """
        gets bler for given cell
        @param cell: cell id
        @param direction: dl or ul
        @return: bler for cell
        """
        return ThroughputMeasurement().get_cell_bler(cell, direction)

    @staticmethod
    def bler_for_cell_should_not_exceed(cell, direction, margin=10):
        """

        @param cell:  cell id
        @param direction: dl or ul
        @param margin: max allowed bler
        @return: pass or fail test execution
        """
        return ThroughputAnalyze.expected_bler_for_cell_should_not_exceed(cell, direction, margin)

    @staticmethod
    def clear_statistics_for_ues(ues, type, range_of_ues=None, data_stats_gathering_span=0):
        """
        Clears statistics for ues
        :param ues:                         ues
        :param type:                        type
        :param data_stats_gathering_span:   Data statistics gathering span
        """
        DataTraffic().clear_statistics_for_ues(ues, type, range_of_ues, data_stats_gathering_span)

    @staticmethod
    def verify_if_throughput_on_all_ue_bearers_is_equal(
        ue_id, throughput, margin, direction=None, selection_type='average', retry=0
    ):
        """
        Checks if selected throughput on all ue bearers is equal in given margin
        :param ue_id:                   ue_id
        :param direction:               'dl' or 'ul'
        :param throughput:              expected throughput
        :param selection_type:          'current' or 'minimum' or 'maximum' or 'average'
        :param margin:                  possible margin of error
        :param retry:                   number of retry after incorrect read egate output
        """
        ThroughputAnalyze.throughput_on_all_ue_bearers_is_equal(
            ue_id, selection_type, direction, throughput, margin, retry
        )

    @staticmethod
    def start_data_traffic_on_all_available_bearers(ue_id, throughput, direction='both', traffic_period=None):
        """
        Starts data traffic on all bearers in given direction or in both directions for UE
        :param ue_id:                   Id of UE
        :param throughput:              Throughput
        :param direction:               Direction 'ul' or 'dl', if not given starts traffic in both
        :param traffic_period:          [optional] Period in which data will be generated
        :return: None
        """
        DataTraffic().start_data_traffic_on_all_available_bearers(ue_id, throughput, direction, traffic_period)

    @staticmethod
    def start_traffic_for_multiple_bearers(ues, first_bearer_id, last_bearer_id, throughput, direction):
        DataTraffic().start_traffic_for_multiple_bearers(ues, first_bearer_id, last_bearer_id, throughput, direction)

    @staticmethod
    def get_cell_retx_number_in_ul(cell_id, retry=5):
        return ThroughputMeasurement().get_ul_retx_for_cell(cell_id, retry)
